from pathlib import Path
import json
r=Path(__file__).resolve().parents[1];catalog=r/'design/gods0341.json'
ids=['suisei','miko','aki','fubuki','ayame','choco','korone','okayu','pekora','noel','watame','towa','lamy','polka','koyori','lui','raden','hajime','su','vivi','sopia','mela']
names=['스이세이','미코','아키','후부키','아야메','초코센','코로네','오카유','페코라','노엘','와타메','토와','라미','폴카','코요리','루이','라덴','하지메','스우','비비','소피아','메라']
if not catalog.exists():
 legacy=json.loads((r/'design/legacy-god-art-skills.json').read_text(encoding='utf-8-sig'))
 extras={('suisei',2):('별 중첩 명중 보조','별2개 이상에서 명중 보조. 기존0.24 수치 재검토.'),('suisei',4):('별의 계승','처치 보상 공격으로 새 적의 별을2개부터 시작.'),('miko',2):('신사 처치 회복','신사 안 처치 회복, 최대체력 초과 회복은 보호막.'),('aki',2):('장미의 양분','정원 안 가시3중첩 적 처치 시 MP 회복.'),('fubuki',2):('여우 협공','속은 적에게 첫 직접 적중 시 분신의 추가 여우불.'),('ayame',2):('귀인의 잔심','표식 적 인접 처치 후 다음 새 적 첫 근접 공격 보조.')}
 gods=[]
 for gid,name in zip(ids,names):
  slots=[]
  for tier in range(1,6):
   base={'id':f'{gid}.tier{tier}','tier':tier,'piety_required':{1:30,2:50,3:75,4:100,5:120}[tier],'runtime_status':'not_implemented','balance_status':'review_pending','cost':{'mp':None,'piety':None,'aut':None}}
   if tier in [1,3,5]:
    row=legacy[gid][[1,3,5].index(tier)];mode=row[1]
    base.update(name=row[0],kind='mixed' if '사용' in mode and '자동' in mode else 'active' if '사용' in mode else 'passive_with_targeting' if '지정' in mode else 'passive',summary=row[2],vfx_reference=row[3],design_status='legacy_reference_requires_review',legacy_activation_label=mode)
   elif (gid,tier) in extras:
    title,summary=extras[(gid,tier)];base.update(name=title,kind='passive',summary=summary,design_status='legacy_passive_requires_review')
   else:base.update(name='추가 패시브 검토 슬롯',kind='passive',summary='공통 자리는 준비하되 채택 여부·효과·수치는 개별 검토. 빈 슬롯을 자동으로 강화 효과로 취급하지 않음.',design_status='reserved_optional')
   slots.append(base)
  gods.append({'id':gid,'name_ko':name,'identity_status':'registered','runtime_status':'not_implemented','reference':'migration/legacy024/holo-campaign.cc','ability_slots':slots,'resource_definitions':[],'wrath_status':'port_pending','migration_notes':['기존 설명은 참고용이며0.34.1 전투 적용 완료를 뜻하지 않음.']+(['0.34.1에는 음식이 없어 전용 주먹밥·권능 방식 결정 필요.'] if gid=='okayu' else [])+(['마법 개편 컨셉과 실제0.24 전투 구현의 차이를 확인해야 함.'] if gid in ['vivi','sopia','mela'] else [])})
 data={'schema_version':1,'engine':'0.34.1','scope':'Structure first; no god combat effect is enabled by this catalog.','piety':{'maximum':200,'tier_thresholds':[30,50,75,100,120],'status':'legacy thresholds carried as editable defaults; not newly balanced'},'event_contract':['turn_elapsed','voluntary_move','direct_hit','damage_taken','xp_kill','spell_cast','level_leave'],'gods':gods}
 catalog.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
data=json.loads(catalog.read_text(encoding='utf-8'))
assert [g['id'] for g in data['gods']]==ids
rows=[];kinds={'active':'ability_kind::active','passive':'ability_kind::passive','mixed':'ability_kind::mixed','passive_with_targeting':'ability_kind::passive_with_targeting'}
quote=lambda s:json.dumps(s,ensure_ascii=True)
for g in data['gods']:
 assert len(g['ability_slots'])==5
 abilities=[]
 for slot in g['ability_slots']:
  assert slot['runtime_status']=='not_implemented'
  abilities.append('{'+','.join([quote(slot['id']),quote(slot['name']),str(slot['tier']),str(slot['piety_required']),kinds[slot['kind']],'false'])+'}')
 rows.append('{'+quote(g['id'])+','+quote(g['name_ko'])+', {'+','.join(abilities)+'}}')
out=r/'engine/upstream/crawl-ref/source/holo34-catalog.inc'
out.write_text('// Generated by scripts/generate-god-structure.py; edit design/gods0341.json.\nstatic const god_definition registry[] = {\n'+',\n'.join(rows)+'\n};\nstatic const char catalog_json[] = R"HC34('+json.dumps(data,ensure_ascii=False,indent=2)+')HC34";\n',encoding='utf-8')
preview=r/'preview/gods';preview.mkdir(parents=True,exist_ok=True)
(preview/'catalog.js').write_text('window.godCatalog = '+json.dumps(data,ensure_ascii=False)+';\n',encoding='utf-8')
print('Generated 22 gods /110 structural slots; no combat handlers enabled.')
